import numpy as np

def analyze_collision_physics_detailed(doc, scope):
    motion = get_motion_data(doc, scope)
    event_node = node_by_title(doc, f"{scope}: Events")
    if not event_node: return

    print(f"--- Detailed Collision Physics in {scope} ---")
    for line in event_node.get('lines', []):
        match = re.match(r'Frame (\d+): (Object \d+).*?collides with (Object \d+)', line)
        if match:
            frame = int(match.group(1))
            obj1_id = match.group(2)
            obj2_id = match.group(3)

            m1 = motion.get(obj1_id, [])
            m2 = motion.get(obj2_id, [])

            # Find record immediately before and after
            def get_closest(m, f, before=True):
                best = None
                for r in m:
                    if before and r['frame'] < f:
                        if best is None or r['frame'] > best['frame']:
                            best = r
                    elif not before and r['frame'] > f:
                        if best is None or r['frame'] < best['frame']:
                            best = r
                return best

            s1_pre, s1_post = get_closest(m1, frame, True), get_closest(m1, frame, False)
            s2_pre, s2_post = get_closest(m2, frame, True), get_closest(m2, frame, False)

            if s1_pre and s1_post and s2_pre and s2_post:
                v1_pre = np.array([s1_pre['vx'], s1_pre['vy']])
                v1_post = np.array([s1_post['vx'], s1_post['vy']])
                v2_pre = np.array([s2_pre['vx'], s2_pre['vy']])
                v2_post = np.array([s2_post['vx'], s2_post['vy']])

                print(f"Frame {frame}: {obj1_id} & {obj2_id}")
                print(f"  v1: {v1_pre} -> {v1_post}")
                print(f"  v2: {v2_pre} -> {v2_post}")
                print(f"  Sum pre: {v1_pre + v2_pre}, Sum post: {v1_post + v2_post}")
                # Check if it's a simple swap
                if np.allclose(v1_post, v2_pre) and np.allclose(v2_post, v1_pre):
                    print("  Result: Simple Swap")
                elif np.allclose(v1_post + v2_post, v1_pre + v2_pre):
                    print("  Result: Momentum Conserved (not simple swap)")
                else:
                    print("  Result: Other")

